<?php
/* TEMPORARY (owner, 14 Nov 2026): saves 5 Art Education drafts (with their free cover pictures) and new Art Events drafts,
   all unpublished, after a full backup. Also lists the Art Map places and their map coordinates (read only).
   Locked by a secret key, runs once. Removed straight after. */
if (!hash_equals('69eea358825785e19ab80840c127d68350812b3fcd33407978b18020993f0590', hash('sha256', (string) ($_GET['k'] ?? '')))) { http_response_code(404); exit; }
require_once __DIR__ . '/config.php';
header('Content-Type: text/plain; charset=utf-8'); header('Cache-Control: no-store'); header('X-Robots-Tag: noindex');
@set_time_limit(300);
$db = getDB();
$p = json_decode(base64_decode(''), true);
$has = function (string $slug) use ($db) { $s = $db->prepare('SELECT id, status FROM articles WHERE slug = :s'); $s->execute([':s' => $slug]); return $s->fetch(); };
$ok = true;
foreach ($p['edu'] as $a) { $h = $has($a['slug']); $f = is_file(__DIR__ . '/' . $a['img']); if (!$f) $ok = false;
    echo 'edu ', $a['slug'], ' | exists: ', $h ? ('yes #' . $h['id'] . ' ' . $h['status']) : 'no', ' | picture: ', $f ? 'ok' : 'MISSING', "\n"; }
foreach ($p['ev'] as $a) { $h = $has($a['slug']); echo 'event ', $a['slug'], ' | exists: ', $h ? ('yes #' . $h['id'] . ' ' . $h['status']) : 'no', "\n"; }
echo "\nevent drafts now:\n";
foreach ($db->query("SELECT id, title_en, event_start_date FROM articles WHERE type = 'event' ORDER BY id") as $r) echo '  #', $r['id'], ' ', $r['title_en'], ' ', $r['event_start_date'], "\n";
if (($_GET['a'] ?? '') === 'map') {
    echo "\nart_places published (id|kind|region|name_en|city_en|lat|lng):\n";
    foreach ($db->query("SELECT id, kind, region, name_en, city_en, lat, lng FROM art_places WHERE status = 'published' ORDER BY id") as $r) echo implode('|', array_map('strval', $r)), "\n";
    echo "\ninstitutes shown (id|name_en|city_en):\n";
    foreach ($db->query("SELECT id, name_en, city_en FROM institutes WHERE is_active = 1 ORDER BY id") as $r) echo implode('|', array_map('strval', $r)), "\n";
    exit;
}
if (($_GET['a'] ?? '') !== 'run') exit;
if (is_file(__DIR__ . '/.logs/zz-ae5-done')) { echo "already run\n"; exit; }
if (!$ok) { echo "stopped: a picture is missing, nothing changed\n"; exit; }
$dbName = (string) $db->query('SELECT DATABASE()')->fetchColumn();
/* 1. full backup */
$dir = __DIR__ . '/.backups';
if (!is_dir($dir)) { @mkdir($dir, 0700, true); }
if (!is_file($dir . '/.htaccess')) { @file_put_contents($dir . '/.htaccess', "Require all denied\n"); }
$file = $dir . '/db-' . preg_replace('/[^a-z0-9_]/i', '', $dbName) . '-' . gmdate('Ymd-His') . '.sql.gz';
$gz = gzopen($file, 'wb6');
if (!$gz) { echo "backup FAILED: cannot write\n"; exit; }
gzwrite($gz, "-- Oweili full backup " . gmdate('c') . "\nSET NAMES utf8mb4;\nSET FOREIGN_KEY_CHECKS=0;\n");
$tables = $db->query('SHOW FULL TABLES WHERE Table_type = "BASE TABLE"')->fetchAll(PDO::FETCH_COLUMN);
$rows = 0;
foreach ($tables as $t) {
    $t = str_replace('`', '', (string) $t);
    $c = $db->query("SHOW CREATE TABLE `$t`")->fetch(PDO::FETCH_NUM);
    gzwrite($gz, "\nDROP TABLE IF EXISTS `$t`;\n" . $c[1] . ";\n");
    $st = $db->query("SELECT * FROM `$t`");
    while ($r = $st->fetch(PDO::FETCH_NUM)) {
        $vals = array_map(fn($v) => $v === null ? 'NULL' : $db->quote((string) $v), $r);
        gzwrite($gz, "INSERT INTO `$t` VALUES (" . implode(',', $vals) . ");\n");
        $rows++;
    }
}
gzwrite($gz, "\nSET FOREIGN_KEY_CHECKS=1;\n");
gzclose($gz);
$size = (int) filesize($file);
if ($size < 500) { echo "backup FAILED (too small)\n"; exit; }
echo "backup ok: .backups/" . basename($file) . " (" . count($tables) . " tables, $rows rows, $size bytes)\n";

$dir = __DIR__ . '/uploads/articles';
if (!is_dir($dir)) @mkdir($dir, 0755, true);
$ins = $db->prepare("INSERT INTO articles (type, slug, title_en, title_ar, body_en, body_ar, cover_image_path, author_user_id, status, event_start_date, event_end_date, event_location_en, event_location_ar)
                     VALUES (:t, :s, :te, :ta, :be, :ba, :c, NULL, 'draft', :sd, :ed, :le, :la)");
foreach ($p['edu'] as $a) {
    if ($has($a['slug'])) { echo 'skipped (already there): ', $a['slug'], "\n"; continue; }
    $name = bin2hex(random_bytes(16)) . '.jpg';
    if (!@copy(__DIR__ . '/' . $a['img'], $dir . '/' . $name)) { echo 'copy failed, skipped: ', $a['slug'], "\n"; continue; }
    $ins->execute([':t' => 'art_education', ':s' => $a['slug'], ':te' => $a['title_en'], ':ta' => $a['title_ar'], ':be' => $a['body_en'], ':ba' => $a['body_ar'],
                   ':c' => 'uploads/articles/' . $name, ':sd' => null, ':ed' => null, ':le' => '', ':la' => '']);
    echo 'saved draft #', $db->lastInsertId(), ' ', $a['slug'], "\n";
}
foreach ($p['ev'] as $a) {
    if ($has($a['slug'])) { echo 'skipped (already there): ', $a['slug'], "\n"; continue; }
    $ins->execute([':t' => 'event', ':s' => $a['slug'], ':te' => $a['title_en'], ':ta' => $a['title_ar'], ':be' => $a['body_en'], ':ba' => $a['body_ar'],
                   ':c' => '', ':sd' => $a['start'], ':ed' => $a['end'], ':le' => $a['loc_en'], ':la' => $a['loc_ar']]);
    echo 'saved draft #', $db->lastInsertId(), ' ', $a['slug'], "\n";
}
@file_put_contents(__DIR__ . '/.logs/zz-ae5-done', gmdate('c'));
echo "done\n";
